import { errors } from "@appport/protocol";
import { readExport } from "../legacy/crm.mjs";

// Who to send a customer's invoices to.
//
// Reads the customer record straight from the CRM export (readExport). This is
// the same data source customers.lookup.mjs uses, so answers on existing state
// stay the same. It no longer goes through the lookupCustomer handler.
//
// Notes for the reviewing agent:
// - No separate "customer store" module was visible to me. The only store the
//   current code reaches is readExport() in src/legacy/crm.mjs, so this reads
//   that directly. If the application has a different store, I did not use it.
//   Moving to a different store would also need a check that it holds the same
//   rows as the export, or answers could change.
// - The published contract still declares
//   requires: [{ id: "customer", relationship: "observes",
//   target: customers.lookup@1 }].
//   This module no longer calls that capability's handler. The contract cannot
//   change here (the digest is fixed), so that declaration is now looser than
//   what the code does.
// - Lookup and field mapping copy lookupCustomer exactly: strict equality on
//   cust_id, name <- full_name, email <- mail. A missing customer raises
//   errors.notFound with the same message.
export async function billingContact(input) {
  const row = readExport().find((r) => r.cust_id === input.customerId);
  if (!row) {
    throw errors.notFound(`no customer ${input.customerId}`);
  }
  return { customerId: row.cust_id, name: row.full_name, email: row.mail };
}
=== END FILE ===

